    def helper(a):
        return (
            sum(abs(x1 - x2) + abs(y1 - y2)
                for (x1, y1), (x2, y2) in zip_longest(points[:-1], points[1:], fillvalue=(0, 0))),
            *points
        )

    def points(a):
        x = a[:n // 2]
        y = a[n // 2:]
        return list(zip(x, y))

    a.sort()
    l = helper(points(a))
    r = helper(points(reversed(a)))
