from collections import Counter

def solve():
    n = int(input())
    a = list(map(int, input().split()))
    count = Counter(a)
    neg_count = count[-1]
    pos_count = count[1]

    diff = abs(neg_count - pos_count)

    if diff % 2 == 0:
        return min(diff // 2 + (neg_count > pos_count), n - diff)
    elif (diff - 1) % 4 == 0 or neg_count < pos_count:
        return (diff - 1) // 2 % (n - diff)

    return min(abs(neg_count - pos_count) // 2 + (pos_count < neg_count), n - abs(pos_count - neg_count))
